// Inference COMPOSED through the Union's own Logical Inference Service Section, not a private
// provider client. We hire the LISS routing harness (run-one-exchange.mjs) — it derives the
// child team by a stated rule, invokes it once, verifies the exchange against the firm's
// schema, and records its own books. We do not reimplement provider routing.
//
// REAL CONSTRAINT (surfaced, not hidden): LISS and each child team are BOUNDED PILOTS capped
// at 10 seated exchanges (LISS_INFERENCE_PILOT_CAP / *_INFERENCE_PILOT_CAP). Past that they
// refuse until a Leader decision raises the cap. Scaling the solve loop past ~10 live calls
// needs that decision and/or the batch dispatch path (contract-cheapest-inference /
// dispatch-jsonl.mjs), which also does supplier cost-ranking and output-contract verification.
import { spawnSync } from "node:child_process";
import { writeFileSync, mkdtempSync, existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

function lissHarness() {
  if (process.env.LISS_HARNESS) return process.env.LISS_HARNESS;
  return fileURLToPath(
    new URL(
      "../../red-cup-engineering/services/logical-inference-service-section/run-one-exchange.mjs",
      import.meta.url,
    ),
  );
}

export function lissAvailable() {
  return existsSync(lissHarness());
}

// Hire LISS for one exchange. Returns the completion text, or throws with the typed refusal
// grounds (including the bounded-pilot cap refusal) — never a silent fallback to a raw provider.
export async function complete({ model = "nvidia/nemotron-3-nano-30b-a3b", messages, maxTokens = 2048, params } = {}) {
  const harness = lissHarness();
  if (!existsSync(harness)) throw new Error(`LISS harness not found at ${harness} (set LISS_HARNESS)`);
  const packet = { model, messages, "max-tokens": maxTokens, ...(params ? { params } : {}) };
  const dir = mkdtempSync(join(tmpdir(), "liss-packet-"));
  const packetPath = join(dir, "packet.json");
  writeFileSync(packetPath, JSON.stringify(packet));
  try {
    const res = spawnSync(process.execPath, [harness, packetPath], { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 });
    if (res.status === 3) throw new Error(`LISS refused (bounded-pilot cap reached): ${(res.stderr || "").trim()}`);
    let record;
    try { record = JSON.parse(res.stdout); } catch {
      throw new Error(`LISS produced no parseable exchange record (exit ${res.status}): ${(res.stderr || "").slice(0, 300)}`);
    }
    if (record.outcome === "completion") return record.completion?.text ?? "";
    throw new Error(`LISS settled as refusal: ${record.refusal?.grounds || "unknown grounds"}`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// Extract the first fenced ```diff (or ```patch / ```) block from a model reply.
export function extractDiff(text) {
  const fenced = /```(?:diff|patch)?\s*\n([\s\S]*?)```/i.exec(String(text || ""));
  const body = fenced ? fenced[1] : String(text || "");
  return body.trim() ? body.replace(/\s+$/, "") + "\n" : null;
}

