--- SOURCE red-cup-engineering/services/logical-inference-service-section/run-one-exchange.mjs sha256=980830f33f3fa1702a804148a7f4265c3aa6b653472ddc178a644e291adac4b0 bytes=16265 ---
#!/usr/bin/env node
// run-one-exchange.mjs — the Logical Inference Service Section's own routing
// harness. LISS is now itself contractable: a caller sends one context
// packet here without needing to know or care which of the section's
// chat-completion-capable child teams (nvidia-inference-team,
// openai-inference-team, anthropic-inference-team, claude-code-inference-team,
// gemini-inference-team, groq-inference-team, openrouter-inference-team,
// github-models-inference-team) actually serves it.
//
// Reads a context packet (JSON: model, messages, optional max-tokens/params),
// derives exactly one target child team by a stated, inspectable rule (never
// a hidden or trust-ordered selection — see content/contracts/
// liss-inference-service.json), and either (--dry-run) validates the packet,
// reports the derived team and the child's own auth-presence with no live
// exchange, or invokes that team's own run-one-exchange.mjs harness exactly
// once. The exhausted NVIDIA model-prefix default is a compatibility bridge
// into the cheapest-sufficient fabric; explicit provider overrides and exact
// provider prefixes retain their legacy single-team semantics. See README.md and
// content/contracts/liss-inference-service.json for the contract this
// realizes, and lib/schemas/inference-exchange.schema.json (in the
// executive office's schema pool) for the class every written exchange
// record is validated against.
//
// Usage:
//   node run-one-exchange.mjs path/to/packet.json [--dry-run]
//
// Routing rule (stated here so it is never hidden — see also the contract):
//   1. packet.params.provider, when present, must name one of the routable
//      team ids below; used as-is (explicit caller override).
//   2. else packet.model matched against a prefix table:
//        ^claude-                          -> anthropic-inference-team
//        ^(gpt-|o1-|o3-|o4-|chatgpt-)      -> openai-inference-team
//        ^gemini-                          -> gemini-inference-team
//        anything else                     -> nvidia-inference-team (default)
//   groq-, openrouter-, and github-models-inference-team serve models whose
//   ids collide with other catalogs (llama-*, vendor/model paths), so they
//   are reachable only by the explicit params.provider override — never by
//   prefix inference. Their providers' free-tier claims are Leader-supplied
//   and unverified until exercised; each team's key is client-supplied at
//   invocation (see each team's own README and contract).
//   notebooklm-inference-team is never a routing target here: its exchange
//   shape (emsenn/schema/exchange, a closed artifact-type menu) is not a
//   chat-completion packet at all.
//
// Env:
//   LISS_INFERENCE_EXCHANGE_FUEL_SECONDS — wall-clock budget wrapping the
//     derived child's own invocation (default 150 — the child's own default
//     budget, 120s, plus routing/mirroring overhead margin).
//   LISS_INFERENCE_PILOT_CAP — bounded-pilot cap on this unit's own
//     content/exchanges/*.json when explicitly set. Unset means no aggregate
//     lifetime cap; supplier and fabric capacity controls still apply.

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve as resolvePath } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { dispatchJobs } from "./src/inference-fabric.mjs";
import { fabricResultToLegacyRecord, legacyPacketToFabricJob, loadLegacyBridgeRegistry } from "./src/legacy-fabric-bridge.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const EXCHANGES_DIR = join(HERE, "content", "exchanges");
const FABRIC_REGISTRY = process.env.LISS_INFERENCE_FABRIC_REGISTRY ?? join(HERE, "content", "config", "inference-fabric-runtime.json");

const FUEL_SECONDS = Number(process.env.LISS_INFERENCE_EXCHANGE_FUEL_SECONDS ?? 150);
function optionalNonnegativeInteger(raw, label) {
  if (raw === undefined || raw === "") return null;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 0) fail(2, `${label} must be a nonnegative integer when set`);
  return value;
}

const PILOT_CAP = optionalNonnegativeInteger(process.env.LISS_INFERENCE_PILOT_CAP, "LISS_INFERENCE_PILOT_CAP");
const DRY_RUN = process.argv.includes("--dry-run");

const TEAM_SCRIPTS = {
  "nvidia-inference-team": join(HERE, "services", "nvidia-inference-team", "run-one-exchange.mjs"),
  "openai-inference-team": join(HERE, "services", "openai-inference-team", "run-one-exchange.mjs"),
  "anthropic-inference-team": join(HERE, "services", "anthropic-inference-team", "run-one-exchange.mjs"),
  "claude-code-inference-team": join(HERE, "services", "claude-code-inference-team", "run-one-exchange.mjs"),
  "gemini-inference-team": join(HERE, "services", "gemini-inference-team", "run-one-exchange.mjs"),
  "groq-inference-team": join(HERE, "services", "groq-inference-team", "run-one-exchange.mjs"),
  "openrouter-inference-team": join(HERE, "services", "openrouter-inference-team", "run-one-exchange.mjs"),
  "github-models-inference-team": join(HERE, "services", "github-models-inference-team", "run-one-exchange.mjs"),
};

function fail(code, message) {
  process.stderr.write(message.endsWith("\n") ? message : `${message}\n`);
  process.exit(code);
}

// ── bounded-pilot guard ──────────────────────────────────────────────────
// Counts this unit's own non-archived content/exchanges/*.json records —
// separate from, and in addition to, whichever derived child team's own
// guard applies once invoked.
function countSeatedExchanges() {
  if (!existsSync(EXCHANGES_DIR)) return 0;
  return readdirSync(EXCHANGES_DIR, { withFileTypes: true }).filter(
    (entry) => entry.isFile() && entry.name.endsWith(".json"),
  ).length;
}

const seated = countSeatedExchanges();
if (PILOT_CAP !== null && seated >= PILOT_CAP) {
  fail(
    3,
    `refused: content/exchanges/ already holds ${seated} record(s), at or above the explicitly configured LISS_INFERENCE_PILOT_CAP (${PILOT_CAP}).`,
  );
}

// ── packet load and validation ──────────────────────────────────────────
const packetPath = process.argv[2];
if (!packetPath || packetPath.startsWith("--")) {
  fail(2, "usage: node run-one-exchange.mjs path/to/packet.json [--dry-run]");
}

const absPacketPath = resolvePath(packetPath);
let packetRaw;
try {
  packetRaw = readFileSync(absPacketPath, "utf8");
} catch (e) {
  fail(2, `cannot read packet at ${packetPath}: ${e.message}`);
}

let packet;
try {
  packet = JSON.parse(packetRaw);
} catch (e) {
  fail(2, `packet at ${packetPath} is not valid JSON: ${e.message}`);
}

function validatePacket(p) {
  const errs = [];
  if (typeof p !== "object" || p === null || Array.isArray(p)) {
    errs.push("packet must be a JSON object");
    return errs;
  }
  if (typeof p.model !== "string" || p.model.length === 0) {
    errs.push("packet.model must be a non-empty string");
  }
  if (!Array.isArray(p.messages) || p.messages.length === 0) {
    errs.push("packet.messages must be a non-empty array");
  } else {
    p.messages.forEach((m, i) => {
      if (typeof m !== "object" || m === null || Array.isArray(m)) {
        errs.push(`packet.messages[${i}] must be an object`);
        return;
      }
      if (typeof m.role !== "string" || !["system", "user", "assistant"].includes(m.role)) {
        errs.push(`packet.messages[${i}].role must be one of system, user, assistant`);
      }
      if (typeof m.content !== "string" || m.content.length === 0) {
        errs.push(`packet.messages[${i}].content must be a non-empty string`);
      }
    });
  }
  return errs;
}

const packetErrors = validatePacket(packet);
if (packetErrors.length) {
  fail(2, `packet at ${packetPath} is invalid:\n  - ${packetErrors.join("\n  - ")}`);
}

// ── routing derivation ───────────────────────────────────────────────────
// Stated and deterministic, per content/contracts/liss-inference-service.json
// — never a hidden or trust-ordered selection.
function deriveTeam(p) {
  const override = p.params && typeof p.params.provider === "string" ? p.params.provider : null;
  if (override) {
    if (!Object.prototype.hasOwnProperty.call(TEAM_SCRIPTS, override)) {
      return {
        error: `packet.params.provider names "${override}", which is not one of the routable teams: ${Object.keys(TEAM_SCRIPTS).join(", ")}`,
      };
    }
    return { team: override, basis: "explicit-override" };
  }
  const model = p.model || "";
  if (/^claude-/i.test(model)) return { team: "anthropic-inference-team", basis: "model-prefix" };
  if (/^(gpt-|o1-|o3-|o4-|chatgpt-)/i.test(model)) return { team: "openai-inference-team", basis: "model-prefix" };
  if (/^gemini-/i.test(model)) return { team: "gemini-inference-team", basis: "model-prefix" };
  return { team: "nvidia-inference-team", basis: "model-prefix-default" };
}

const routing = deriveTeam(packet);

function generateId() {
  const now = new Date();
  const pad = (n, w = 2) => String(n).padStart(w, "0");
  const stamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1)}${pad(now.getUTCDate())}-${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}`;
  const rand = randomBytes(3).toString("hex");
  return `liss-exchange-${stamp}-${rand}`;
}

// Validate a would-be exchange record against emsenn/schema/inference-exchange
// by shelling out to read-a-schema.js — the one validator. Resolution walks
// up from this script's own location as a fallback when the known seat has
// moved, exactly as the child teams' own harnesses do.
function validateExchangeRecord(record) {
  const reader = findReadASchema();
  if (!reader) {
    return { ranSchemaCheck: false, ok: null, errors: [] };
  }
  const result = spawnSync(
    process.execPath,
    [reader, "emsenn/schema/inference-exchange", "--pool", resolvePath(dirname(reader), "..", "..", "schemas")],
    { input: JSON.stringify(record), encoding: "utf8" },
  );
  let verdict;
  try {
    verdict = JSON.parse(result.stdout);
  } catch {
    return { ranSchemaCheck: true, ok: false, errors: [`read-a-schema.js returned unparseable output: ${(result.stderr || result.stdout || "").trim()}`] };
  }
  return { ranSchemaCheck: true, ok: verdict.ok === true, errors: verdict.errors ?? [] };
}

function findReadASchema() {
  const candidate = fileURLToPath(
    new URL(
      "../../../../../board-of-directors/services/executive-office/lib/management/skills/read-a-schema.js",
      import.meta.url,
    ),
  );
  if (existsSync(candidate)) return candidate;
  let d = HERE;
  for (;;) {
    const at = join(d, "lib/management/skills/read-a-schema.js");
    if (existsSync(at)) return at;
    const up = dirname(d);
    if (up === d) return null;
    d = up;
  }
}

function writeAndReport(record, exitCode) {
  const validation = validateExchangeRecord(record);
  if (validation.ranSchemaCheck && validation.ok === false) {
    process.stderr.write(
      `warning: the mirrored exchange record failed schema validation against emsenn/schema/inference-exchange:\n  - ${validation.errors.join("\n  - ")}\nwriting it anyway is refused; nothing is seated.\n`,
    );
    process.exit(1);
  }
  if (!validation.ranSchemaCheck) {
    process.stderr.write(
      "note: read-a-schema.js could not be found — full schema validation was not run; writing the record with only this script's own by-hand field checks applied.\n",
    );
  }
  const outPath = join(EXCHANGES_DIR, `${record.id}.json`);
  writeFileSync(outPath, JSON.stringify(record, null, 2) + "\n");
  process.stdout.write(JSON.stringify(record, null, 2) + "\n");
  process.exit(exitCode);
}

// ── dry-run: validate, derive, and forward the child's own dry-run check ──
if (DRY_RUN) {
  if (routing.error) {
    process.stdout.write(
      JSON.stringify({ ok: false, "dry-run": true, "packet-valid": true, "routing-error": routing.error }, null, 2) + "\n",
    );
    process.exit(0);
  }
  const childScript = TEAM_SCRIPTS[routing.team];
  const childResult = spawnSync(process.execPath, [childScript, absPacketPath, "--dry-run"], { encoding: "utf8" });
  let childReport = null;
  try {
    childReport = JSON.parse(childResult.stdout);
  } catch {
    childReport = { ok: false, note: "derived team's own --dry-run output was not parseable JSON", stderr: (childResult.stderr || "").trim() };
  }
  process.stdout.write(
    JSON.stringify(
      {
        ok: true,
        "dry-run": true,
        "packet-valid": true,
        "derived-team": routing.team,
        "derivation-basis": routing.basis,
        "child-dry-run-report": childReport,
      },
      null,
      2,
    ) + "\n",
  );
  process.exit(0);
}

// ── live run ──────────────────────────────────────────────────────────────
// A routing failure (an unresolvable explicit override) settles as a typed
// refusal on this unit's own books — never an untyped error — with no child
// team invoked.
if (routing.error) {
  const record = {
    id: generateId(),
    packet,
    outcome: "refusal",
    refusal: { grounds: routing.error, unmet: ["unroutable-provider-override"] },
    cost: { "fuel-consumed": 0, "wall-time-seconds": 0, denomination: "liss-routing-decisions" },
  };
  writeAndReport(record, 0);
}

// The old catch-all selected NVIDIA for every unrecognized model, but that
// bounded pilot is exhausted. Preserve exact/explicit legacy selections while
// allowing the catch-all customers to buy a verified resolution from the
// current fabric instead of receiving a permanent administrative refusal.
if (routing.team === "nvidia-inference-team" && routing.basis === "model-prefix-default") {
  const exchangeId = generateId(), startedAt = Date.now();
  let result;
  try {
    const registry = loadLegacyBridgeRegistry(FABRIC_REGISTRY);
    result = (await dispatchJobs([legacyPacketToFabricJob(packet, `${exchangeId}-fabric`)], registry, { concurrency: 1, attempts: registry.attempts })).records[0];
  } catch (error) {
    result = { attempts: [], refusal: { type: `fabric-bridge-failure:${error.message}` } };
  }
  writeAndReport(fabricResultToLegacyRecord(packet, result, exchangeId, (Date.now() - startedAt) / 1000), 0);
}

const childScript = TEAM_SCRIPTS[routing.team];
const startedAt = Date.now();
const childResult = spawnSync(process.execPath, [childScript, absPacketPath], {
  encoding: "utf8",
  timeout: FUEL_SECONDS * 1000,
  killSignal: "SIGKILL",
});
const wallTime = (Date.now() - startedAt) / 1000;

let childRecord = null;
try {
  childRecord = JSON.parse(childResult.stdout);
} catch {
  childRecord = null;
}

let record;
if (childResult.signal === "SIGKILL") {
  record = {
    id: generateId(),
    packet,
    outcome: "refusal",
    refusal: {
      grounds: `the derived team ${routing.team} did not settle within the ${FUEL_SECONDS}-second wrapping fuel budget and was killed`,
      unmet: ["child-harness-timeout"],
    },
    cost: { "fuel-consumed": 1, "wall-time-seconds": wallTime, denomination: "liss-routing-decisions" },
  };
} else if (!childRecord || typeof childRecord.outcome !== "string") {
  record = {
    id: generateId(),
    packet,
    outcome: "refusal",
    refusal: {
      grounds: `the derived team ${routing.team}'s harness did not produce a parseable settled exchange record. stderr: ${(childResult.stderr || "").slice(0, 500)}`,
      unmet: ["child-harness-unparseable-output"],
    },
    cost: { "fuel-consumed": 1, "wall-time-seconds": wallTime, denomination: "liss-routing-decisions" },
  };
} else {
  // Mirror the child's own settled record verbatim, under an id naming which
  // team was derived, per this unit's own postcondition.
  record = { ...childRecord, id: `${childRecord.id}-via-${routing.team}` };
}

writeAndReport(record, 0);

